function fe = ElementRHS4ConPen_Fr(nnpe,nqptv,wtq,qpmetric,bigN,detj,numdatapt,qp_spread)% called by FitOrientationData2FR%% computes RHS (force) elemental matrix for consistent penalty% determination of an ODF from point-wise datafe= zeros(nnpe,1);feqp= zeros(nnpe,1);bigNqp = zeros(nnpe,1);  for j=1:1:nqptv  	  xkfac=wtq(j)*detj(j)*qpmetric(j);  bigNqp(:) = bigN(:,j);  for k = 1:1:numdatapt  feqp = feqp+xkfac*(bigNqp*qp_spread(k,j));  end  fe = fe + feqp;end